import pandas as pd
import numpy as np
from scipy import stats
from scipy.optimize import curve_fit

# Load all experiments with do_IrrigationRate and CropYield
dfs = {}
for exp_id in [1,4,6,7,9,10,11,12,13]:
    try:
        dfs[exp_id] = pd.read_csv(f'../experiment_{exp_id}_csv')
    except:
        pass

# Find which experiments have do_IrrigationRate
for eid, df in dfs.items():
    has_do = 'do_IrrigationRate' in df.columns
    has_yield = 'CropYield' in df.columns
    print(f"Exp {eid}: has_do_IrrigationRate={has_do}, has_CropYield={has_yield}, n={len(df)}")
    if has_do and has_yield:
        vals = df['do_IrrigationRate'].unique()
        print(f"  do_IrrigationRate levels: {vals}")
        for v in vals:
            subset = df[df['do_IrrigationRate']==v]
            print(f"    rate={v}: mean_yield={subset['CropYield'].mean():.2f}, sd={subset['CropYield'].std():.2f}, n={len(subset)}")
